# Video Transcript and Timeline Extractor - runnable demo (JAH-ATK156-000001)
import re
RANK = 1
SIG = False
SAMPLE = '1\n00:00:01,000 --> 00:00:03,500\nThe archive opens its doors\n\n2\n00:00:03,400 --> 00:00:06,000\nto every curious mind'
def to_sec(ts):
    h, m, rest = ts.split(":"); s, ms = rest.split(",")
    return int(h)*3600 + int(m)*60 + int(s) + int(ms)/1000.0
cues = []
for block in SAMPLE.strip().split("\n\n"):
    lines = block.strip().split("\n")
    if len(lines) >= 3 and "-->" in lines[1]:
        a, b = [x.strip() for x in lines[1].split("-->")]
        cues.append({"start": to_sec(a), "end": to_sec(b), "text": " ".join(lines[2:])})
cues.sort(key=lambda c: c["start"])
merged, cur = [], None
for c in cues:
    if cur and c["start"] <= cur["end"] + 0.2:
        cur["end"] = max(cur["end"], c["end"]); cur["text"] += " " + c["text"]
    else:
        if cur: merged.append(cur)
        cur = dict(c)
if cur: merged.append(cur)
print("parsed cues:", len(cues), "| merged cues:", len(merged))
for c in merged:
    print("[%6.2fs - %6.2fs] %s" % (c["start"], c["end"], c["text"][:60]))
if RANK >= 3:
    dur = max(c["end"] for c in merged) if merged else 0
    print("timeline duration: %.2fs | words: %d" % (dur, sum(len(c["text"].split()) for c in merged)))
if SIG:
    print("Signature lineage stamp: JAH-SIG-VID-" + "JAH-ATK156-000001")
print("record:", "JAH-ATK156-000001", "OK")

